local UIRoleQuestNode = Class("UIRoleQuestNode")
function UIRoleQuestNode:__init()
    self._roleIds = {}
    self._id = 0
end

function UIRoleQuestNode:__delete()
    self._roleIds = nil
    self._id = nil
end

function UIRoleQuestNode:Awake()
end

function UIRoleQuestNode:Start()
end

function UIRoleQuestNode:Refresh(data)
    if not data then
        return
    end
    self._id = checkNumber(data.id)
    self._roleIds = checkTable(data.roleIds)
    if not self._roleIds then
        return
    end

    CfUtils.SetActive(self.TeamGroup1, self._id == 1)
    CfUtils.SetActive(self.controller.gameObject.transform:Find("Root/TeamGroup2"), self._id == 2)
    CfUtils.SetActive(self.controller.gameObject.transform:Find("Root/TeamGroup3"), self._id == 3)

    self:FillSelf()
end

function UIRoleQuestNode:FillSelf()
    for k, v in pairs(self._roleIds) do
        local go
        if self._id == 1 then
            go = self["BtnCardGroup"..k]
        elseif self._id == 2 then
            go = self.controller.gameObject.transform:Find("Root/TeamGroup2/BtnCardGroup"..k)
        elseif self._id == 3 then
            go = self.controller.gameObject.transform:Find("Root/TeamGroup3/BtnCardGroup"..k)
        end

        self:FillRoleInfo(v, k, go)
    end
end

function UIRoleQuestNode:FillRoleInfo(id, ind, go)
    --local go = self["BtnCardGroup"..ind]
    if not go then
        return
    end

    local vo = CfUtils.GetCfVo(AutoIds.IdSetting851, "RoleStoryRoleVo", checkString(id))
    if not vo then
        return
    end
    CfUtils.FillText(go.transform:Find("TxtName"), vo.name)
    local isUnlock = self:IsUnlock(id)
    CfUtils.SetActive(go.transform:Find("LockGroup"), not isUnlock)
    CfUtils.SetActive(go.transform:Find("MarchGroup"), isUnlock)

    CfUtils.SetActive(go.transform:Find("TxtFinish"), isUnlock)
    CfUtils.SetActive(go.transform:Find("TxtNumber"), isUnlock)

    go.transform:Find("ImgRole").transform:GetComponent(UIGrayGraphics):MarkGray(not isUnlock)

    if not isUnlock then 
        return
    end

    local allNum, hasNum = QuestConfMgr:GetInstance():GetRoleStoryOverFinaleIdNum(id)
    CfUtils.FillText(go.transform:Find("TxtNumber"), "<color=#ff1daa>"..hasNum.."</color>/"..allNum)

    SetButtonAction(go, function()
        KCookie.Set("UIMainBattlePanelDialogIndex", 2)
        PhoneUtils.RemoveRoleUnlockRedPoint(id)

        CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIRolePlotDialog, parameters = {roleId = id}},  {
            {id = Constants.UITypeIds.UIMainBattlePanelDialog}
        })
    end)

    local redGo = GameUtils.GetRedPointGo(go.transform:Find("ImgRole"))
    if not isNull(redGo) then
        CfUtils.SetActive(redGo, QuestConfMgr:GetInstance():IsRoleHasDrawRewardId(id) or PhoneUtils.IsRoleUnlockRedPoint(id))
    end
    CfUtils.SetActive(go.transform:Find("MarchGroup"), not (checkNumber(hasNum) == checkNumber(allNum)))
end

function UIRoleQuestNode:IsUnlock(id)
    return self:IsShow(id)
end 

function UIRoleQuestNode:IsShow(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting851, "RoleStoryRoleVo", checkString(id))
    if not vo then
        return false
    end

    return checkNumber(vo.show) == 1
end

function UIRoleQuestNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIRoleQuestNode